mapper.select:
SELECT ITEM_CD, SUB_CLS_NM, TOPIC_NM, PREV_GOV_NM, TERN_START, TERN_END, DESCRIPTION FROM TB_SUBJECT_ITEM_CODE WHERE CLS_CD = #{clsCd}
AND TERN_START IS NOT NULL AND TERN_END IS NOT NULL AND SUBSTRING(REPLACE(REPLACE(REPLACE(REPLACE(TERN_START, '-', ''), '.', ''), '/', ''), ' ', ''), 1, 8) <= SUBSTRING(REPLACE(REPLACE(REPLACE(REPLACE(#{productionDate}, '-', ''), '.', ''), '/', ''), ' ', ''), 1, 8) AND SUBSTRING(REPLACE(REPLACE(REPLACE(REPLACE(TERN_END, '-', ''), '.', ''), '/', ''), ' ', ''), 1, 8) >= SUBSTRING(REPLACE(REPLACE(REPLACE(REPLACE(#{productionDate}, '-', ''), '.', ''), '/', ''), ' ', ''), 1, 8)
AND START_YEAR IS NOT NULL AND END_YEAR IS NOT NULL AND #{productionYear} IS NOT NULL AND #{productionYear} != '' AND START_YEAR <= #{productionYear} AND END_YEAR >= #{productionYear}
ORDER BY PREV_GOV_CD, SUB_CLS_CD, TOPIC_CD, ITEM_CD
